class CommandOptionSpec {
  final String name;
  final String description;
  final CommandOptionKind kind;
  final bool required_;
  final bool autocomplete;
  final List<CommandChoice> choices;

  /// For integers; both 0 for no bounds.
  final PlatformInt64 min;
  final PlatformInt64 max;

  const CommandOptionSpec({
    required this.name,
    required this.description,
    required this.kind,
    required this.required_,
    required this.autocomplete,
    required this.choices,
    required this.min,
    required this.max,
  });

  @override
  int get hashCode =>
      name.hashCode ^
      description.hashCode ^
      kind.hashCode ^
      required_.hashCode ^
      autocomplete.hashCode ^
      choices.hashCode ^
      min.hashCode ^
      max.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is CommandOptionSpec &&
          runtimeType == other.runtimeType &&
          name == other.name &&
          description == other.description &&
          kind == other.kind &&
          required_ == other.required_ &&
          autocomplete == other.autocomplete &&
          choices == other.choices &&
          min == other.min &&
          max == other.max;
}

