@freezed
sealed class MediaEvent with _$MediaEvent {
  const MediaEvent._();

  const factory MediaEvent.connectionState({
    required String serverKey,
    required PlatformInt64 channelId,
    required VoiceConnectionState state,
  }) = MediaEvent_ConnectionState;

  /// The chosen device is missing; the system's default stands in.
  const factory MediaEvent.deviceFellBack({
    required bool output,
    required String device,
  }) = MediaEvent_DeviceFellBack;

  /// No device could be opened.
  const factory MediaEvent.deviceFailed({
    required bool output,
    required String message,
  }) = MediaEvent_DeviceFailed;

  /// The devices plugged in changed.
  const factory MediaEvent.devicesChanged(AudioDevices field0) =
      MediaEvent_DevicesChanged;

  /// Who in this device's voice channel started or stopped speaking,
  /// this device's user too; at most every 50 ms (plan §7.5).
  const factory MediaEvent.speaking({
    required String serverKey,
    required PlatformInt64 channelId,
    required List<SpeakingChange> changes,
  }) = MediaEvent_Speaking;

  /// The microphone's level after processing, in dBFS, about 20 times a
  /// second while a meter is open (`audio_set_level_meter`).
  const factory MediaEvent.inputLevel({required double dbfs}) =
      MediaEvent_InputLevel;

  /// The microphone heard someone speak while this device was muted (at
  /// most every 30 s); for the "You're muted" reminder.
  const factory MediaEvent.speakingWhileMuted() = MediaEvent_SpeakingWhileMuted;

  /// High noise suppression could not keep up on this computer, so
  /// Standard took over (plan §7.3).
  const factory MediaEvent.noiseSuppressionFellBack() =
      MediaEvent_NoiseSuppressionFellBack;

  /// A global hotkey for one of the toggles was pressed (push-to-talk
  /// and the priority key act by themselves).
  const factory MediaEvent.hotkeyPressed({required HotkeyAction action}) =
      MediaEvent_HotkeyPressed;

  /// Someone's camera or screen in this device's voice channel; drawn into
  /// `texture_id` (with `video_init`) while `video_set_wants` asks for it.
  const factory MediaEvent.videoTrackAdded({
    required String serverKey,
    required PlatformInt64 channelId,
    required PlatformInt64 userId,
    required String trackId,
    required VideoTrackKind kind,
    PlatformInt64? textureId,

    /// Its largest layer's size: the shape to draw it in.
    required int width,
    required int height,
  }) = MediaEvent_VideoTrackAdded;
  const factory MediaEvent.videoTrackRemoved({
    required String serverKey,
    required PlatformInt64 channelId,
    required PlatformInt64 userId,
    required String trackId,
  }) = MediaEvent_VideoTrackRemoved;

  /// This device's camera stopped by itself: unplugged, failed, or the
  /// server no longer allows it.
  const factory MediaEvent.cameraStopped({required String message}) =
      MediaEvent_CameraStopped;

  /// This device's screen share ended by itself: the window closed, the
  /// screen went, or the server or voice node stopped it.
  const factory MediaEvent.screenShareStopped({required String message}) =
      MediaEvent_ScreenShareStopped;

  /// How this device's voice connection is doing, once a second while
  /// connected (Phase 2 §12, connection diagnostics).
  const factory MediaEvent.connectionStats({
    required String serverKey,
    required PlatformInt64 channelId,
    required VoiceStats stats,
  }) = MediaEvent_ConnectionStats;
}

