/// Someone in a voice channel.
class VoiceState {
  final PlatformInt64 userId;

  /// `None` once they have left.
  final PlatformInt64? channelId;

  /// Whether this device's session holds it. The same user on another
  /// device is `false`.
  final bool thisDevice;
  final bool selfMute;
  final bool selfDeaf;
  final bool serverMute;
  final bool serverDeaf;

  /// Cannot speak: no Speak permission, or in the AFK channel.
  final bool suppress;
  final bool selfVideo;
  final bool selfStream;

  const VoiceState({
    required this.userId,
    this.channelId,
    required this.thisDevice,
    required this.selfMute,
    required this.selfDeaf,
    required this.serverMute,
    required this.serverDeaf,
    required this.suppress,
    required this.selfVideo,
    required this.selfStream,
  });

  @override
  int get hashCode =>
      userId.hashCode ^
      channelId.hashCode ^
      thisDevice.hashCode ^
      selfMute.hashCode ^
      selfDeaf.hashCode ^
      serverMute.hashCode ^
      serverDeaf.hashCode ^
      suppress.hashCode ^
      selfVideo.hashCode ^
      selfStream.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is VoiceState &&
          runtimeType == other.runtimeType &&
          userId == other.userId &&
          channelId == other.channelId &&
          thisDevice == other.thisDevice &&
          selfMute == other.selfMute &&
          selfDeaf == other.selfDeaf &&
          serverMute == other.serverMute &&
          serverDeaf == other.serverDeaf &&
          suppress == other.suppress &&
          selfVideo == other.selfVideo &&
          selfStream == other.selfStream;
}

/// A voice connection over the last second (Phase 2 §12).
class VoiceStats {
  /// Round trip to the voice node.
  final int? pingMs;

  /// How unevenly the voices heard arrive.
  final double? jitterMs;

  /// Packets lost on the way here and on the way out, 0–100.
  final double? lossInPercent;
  final double? lossOutPercent;

  /// Bits per second, everything included.
  final BigInt bitrateIn;
  final BigInt bitrateOut;

  /// The voice node's host and port.
  final String voiceNode;

  /// This device's camera and screen share encoders, while on: "NVENC
  /// (hardware)", say.
  final String? cameraEncoder;
  final String? screenEncoder;

  const VoiceStats({
    this.pingMs,
    this.jitterMs,
    this.lossInPercent,
    this.lossOutPercent,
    required this.bitrateIn,
    required this.bitrateOut,
    required this.voiceNode,
    this.cameraEncoder,
    this.screenEncoder,
  });

  @override
  int get hashCode =>
      pingMs.hashCode ^
      jitterMs.hashCode ^
      lossInPercent.hashCode ^
      lossOutPercent.hashCode ^
      bitrateIn.hashCode ^
      bitrateOut.hashCode ^
      voiceNode.hashCode ^
      cameraEncoder.hashCode ^
      screenEncoder.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is VoiceStats &&
          runtimeType == other.runtimeType &&
          pingMs == other.pingMs &&
          jitterMs == other.jitterMs &&
          lossInPercent == other.lossInPercent &&
          lossOutPercent == other.lossOutPercent &&
          bitrateIn == other.bitrateIn &&
          bitrateOut == other.bitrateOut &&
          voiceNode == other.voiceNode &&
          cameraEncoder == other.cameraEncoder &&
          screenEncoder == other.screenEncoder;
}
